for i=0,5 do local ok,v=pcall(function()local id=EEex_Sprite_GetInPortraitID(i);if type(id)~='number' or id~=math.floor(id) or id<0 or id>2147483647 then return 'absent' end;local s=EEex_GameObject_Get(id);if not s then return 'OBJECT_MISSING' end;local pos=s.m_pos;local guard=s:getLocalInt('BGX38_GUARD');return 'id='..tostring(s.m_id==id)..' xy='..tostring(pos.x)..','..tostring(pos.y)..' F='..tostring(guard)..' modal='..tostring(s.m_nModalState)..' area='..tostring(s.m_pArea~=nil) end);C:DisplayText('BGX65G P'..i..' '..(ok and v or 'FIELD_ERROR')) end
